function rendererFixture(api){const html=sourceFs.readFileSync(require.resolve('../../apps/desktop/src/settings.html'),'utf8'),script=sourceFs.readFileSync(require.resolve('../../apps/desktop/src/settings.js'),'utf8'),elements=new Map(),actions=[];let ids=100,confirm=false;const classes=new Set();
 class Element{constructor(id,hidden){this.id=id;this.hidden=hidden;this.value='';this.checked=false;this.disabled=false;this.textContent='';this.listeners=new Map();this.focused=false;}addEventListener(name,fn){if(!this.listeners.has(name))this.listeners.set(name,[]);this.listeners.get(name).push(fn);}dispatch(name){const event={defaultPrevented:false,preventDefault(){this.defaultPrevented=true;}};for(const fn of this.listeners.get(name)||[]){const value=fn(event);if(value&&typeof value.then==='function')actions.push(value);}return event;}focus(){this.focused=true;}showModal(){this.open=true;}close(){this.open=false;}}
 for(const m of html.matchAll(/<[^>]*\bid="([^"]+)"[^>]*>/g))elements.set(m[1],new Element(m[1],/\bhidden\b/.test(m[0])));
 const document={getElementById:id=>elements.get(id)||null,documentElement:{classList:{toggle:(name,value)=>{if(value)classes.add(name);else classes.delete(name);},remove:name=>classes.delete(name),contains:name=>classes.has(name)}}};
 const window={anvilDesktop:api,confirm:()=>confirm,crypto:{randomUUID:()=> '55555555-5555-4555-8555-'+String(++ids).padStart(12,'0')}};
 vm.runInNewContext(script,{window,document,console:{error(){assert.fail('RENDERER_RAW_ERROR');},log(){assert.fail('RENDERER_RAW_LOG');}}});
 return{elements,classes,window,document,confirm:value=>{confirm=value;},element:id=>{assert.ok(elements.has(id),'actual HTML id '+id);return elements.get(id);},settleActions:async()=>{for(const p of actions)await p;}};
}

