 const oldNow=Date.now,Client=nativeRuntime.NativeFirstReceiveHumanClient,descriptor=Object.getOwnPropertyDescriptor(Client.prototype,'consumeReceivePhase'),original=descriptor.value;let v,nested=false;Object.defineProperty(Client.prototype,'consumeReceivePhase',{...descriptor,value:async function(...args){const result=await Reflect.apply(original,this,args);if(!nested&&args[2].phase==='STATE'){nested=true;v.clock.offset=4000;const frame=structuredClone(v.phase.frame),issued=new Date(v.f.dependencies.now()).toISOString(),expires=new Date(v.f.dependencies.now()+4000).toISOString();Object.assign(frame.challenge.snapshot,{challengeId:'df111111-1111-4111-8111-111111111111',requestId:'df111111-1111-4111-8111-222222222222',serverNonce:'B'.repeat(42)+'A',issuedAt:issued,expiresAt:expires});frame.challenge.ref={id:frame.challenge.snapshot.challengeId,version:1,contentHash:contentHash(canonicalJson(frame.challenge.snapshot))};Object.assign(frame.request,{challengeRef:frame.challenge.ref,requestId:frame.challenge.snapshot.requestId,serverNonce:frame.challenge.snapshot.serverNonce,issuedAt:issued,expiresAt:expires});Object.assign(v.phase.value.registration,{challengeRef:frame.challenge.ref,observedAt:issued,expiresAt:expires});Object.assign(v.phase.value,{observedAt:issued,expiresAt:expires});const source=v.f.owner.createNativeFirstReceivePhaseProofSource(frame.window);await Reflect.apply(original,this,[frame.window,frame.challenge,frame.request,frame.body,source]);}return result;}});try{v=await registeredPhaseConsumer();const p=v.phase.frame;await assert.rejects(v.client.consumeReceivePhase(p.window,p.challenge,p.request,p.body,v.source),/OUTCOME_UNKNOWN/);assert.equal(nested,true);assert.equal(v.currentPosts(),2);assert.equal(v.signs(),2);assert.equal(v.nativeRequests(),3);assert.equal(v.deadline(),Date.parse(p.request.issuedAt)+10000);}finally{v?.client.disposeReceive();Object.defineProperty(Client.prototype,'consumeReceivePhase',descriptor);Date.now=oldNow;if(v){assert.equal(v.timers.size,0);assert.equal(v.f.timers(),0);}}
